Single Page Application.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Single Page Application container

Container_Boundary("Single Page Application", "Single Page Application") {
    Component("UI Router and Views", "UI Router and Views", "React, TypeScript", "Manages client-side routing, page views, and layout rendering for customers and admin staff.")
    Component("API Client Service", "API Client Service", "TypeScript, Axios/Fetch", "Handles HTTP/REST communication with the AWS API Gateway and Application Load Balancer.")
}

Rel("UI Router and Views", "API Client Service", "Triggers API requests based on user interactions")

@enduml

AWS API Gateway & ALB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_api_gateway_alb, "AWS API Gateway & ALB") {
    Component(Edge_Router_WAF, "Edge Router & WAF", "AWS WAF & Application Load Balancer", "Handles edge security, traffic sanitization, and OWASP protections.")
    Component(API_Management_Routing, "API Management & Routing", "Amazon API Gateway", "Manages API routing and forwards sanitized traffic.")
    Component(Request_Transformation_Caching, "Request Transformation & Caching", "AWS Lambda / API Gateway Caching", "Validates schemas and checks cache for API requests.")
    Component(Service_Mesh_Proxy, "Service Mesh Proxy", "AWS App Mesh (Envoy)", "Forwards backend calls securely using gRPC over mTLS.")
}

Rel(Edge_Router_WAF, API_Management_Routing, "Forwards sanitized traffic", "HTTPS")
Rel(API_Management_Routing, Request_Transformation_Caching, "Validates schemas and checks cache", "Internal API")
Rel(Request_Transformation_Caching, Service_Mesh_Proxy, "Forwards backend calls", "gRPC over mTLS")

@enduml

Amazon ElastiCache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_elasticache, "Amazon ElastiCache") {
    Component(Cache_Router___Cluster_Manager, "Cache Router / Cluster Manager", "Redis Cluster", "Routes data across multi-AZ topology and manages Redis Shards.")
    Component(In_Memory_Recommendation_Store, "In-Memory Recommendation Store", "Redis Hash & Sorted Set", "Stores pre-computed collaborative filtering data and low-latency product recommendations.")
    Component(Session___Token_Cache, "Session & Token Cache", "Redis String / Key-Value Store", "Manages transient shopping cart states, user sessions, and checkout locks.")
}

Rel(Cache_Router___Cluster_Manager, In_Memory_Recommendation_Store, "Routes data across multi-AZ topology", "Redis Protocol")
Rel(Cache_Router___Cluster_Manager, Session___Token_Cache, "Routes data across multi-AZ topology", "Redis Protocol")
@enduml
